const canvas_elem = document.querySelector('#sorting-canvas');
const ctx = canvas_elem.getContext('2d');
const W = 800, H = 500; // canvas dimensions
canvas_elem.width = W;
canvas_elem.height = H;

class Bar {
  constructor(x, y, w, h, value) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.val = value;
  }

  draw(ctx, color) {
    ctx.beginPath();
    ctx.rect(this.x, this.y, this.w, this.h);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.closePath();
  }
}

function makeArray(n, pattern) {
  let arr = [];
  for (let i = 0; i < n; i++) {
    if (pattern === 'Random') {
      arr.push(Math.floor(Math.random() * n));
    } else if (pattern === 'Reverse') {
      arr.push(n - i - 1);
    } else {
      arr.push(i);
      if (Math.random() < 0.1) {
        for (let j = 0; j < 20; j++) {
          arr.push(i);
        }
      }
    }
  }
  return arr;
}

function bubbleSort(arr) {
  let len = arr.length;
  for (let i = 0; i < len - 1; i++) {
    for (let j = 0; j < len - 1 - i; j++) {
      if (arr[j] > arr[j + 1]) {
        let temp = arr[j];
        arr[j] = arr[j + 1];
        arr[j + 1] = temp;
      }
    }
  }
  return arr;
}

function partition(arr, low, high) {
  let pivotIndex = Math.floor((low + high) / 2);
  let pivotValue = arr[pivotIndex];
  let i = low;
  let j = high;
  while (i <= j) {
    while (arr[i] < pivotValue) {
      i++;
    }
    while (arr[j] > pivotValue) {
      j--;
    }
    if (i <= j) {
      let temp = arr[i];
      arr[i] = arr[j];
      arr[j] = temp;
      i++;
      j--;
    }
  }
  return i;
}

function quickSort(arr, low, high) {
  if (low < high) {
    let pivotIndex = partition(arr, low, high);
    quickSort(arr, low, pivotIndex - 1);
    quickSort(arr, pivotIndex + 1, high);
  }
  return arr;
}

function mergeSort(arr, low, high) {
  if (low >= high) return;
  let mid = Math.floor((low + high) / 2);
  mergeSort(arr, low, mid);
  mergeSort(arr, mid + 1, high);
  merge(arr, low, mid, high);
  return arr;
}

function merge(arr, low, mid, high) {
  let temp = [...arr.slice(low, mid + 1)];
  let i = 0, j = 0, k = low;
  while (i < temp.length && j < arr.slice(mid + 1).length) {
    if (temp[i] <= arr[j + mid + 1]) {
      arr[k++] = temp[i++];
    } else {
      arr[k++] = arr[j + mid + 1];
      j++;
    }
  }
  while (i < temp.length) {
    arr[k++] = temp[i++];
  }
}

function heapSort(arr) {
  let len = arr.length;
  for (let i = Math.floor(len / 2) - 1; i >= 0; i--) {
    heapify(arr, i, len);
  }
  for (let i = len - 1; i > 0; i--) {
    let temp = arr[0];
    arr[0] = arr[i];
    arr[i] = temp;
    heapify(arr, 0, i);
  }
  return arr;
}

function heapify(arr, i, len) {
  let max = i;
  let left = 2 * i + 1;
  let right = 2 * i + 2;
  if (left < len && arr[left] > arr[max]) {
    max = left;
  }
  if (right < len && arr[right] > arr[max]) {
    max = right;
  }
  if (max !== i) {
    let temp = arr[i];
    arr[i] = arr[max];
    arr[max] = temp;
    heapify(arr, max, len);
  }
}

function countingSort(arr, exp) {
  let count = new Array(10).fill(0);
  for (let i = 0; i < arr.length; i++) {
    let index = Math.floor(arr[i] / Math.pow(10, exp));
    count[index]++;
  }
  for (let i = 1; i < count.length; i++) {
    count[i] += count[i - 1];
  }
  let output = new Array(arr.length);
  for (let i = arr.length - 1; i >= 0; i--) {
    let index = Math.floor(arr[i] / Math.pow(10, exp)) % 10;
    output[count[index] - 1] = arr[i];
    count[index]--;
  }
  for (let i = 0; i < output.length; i++) {
    arr[i] = output[i];
  }
  return arr;
}

function radixSort(arr) {
  let max = Math.max.apply(null, arr);
  for (let exp = 1; max / exp > 0; exp *= 10) {
    arr = countingSort(arr, Math.floor(Math.log10(exp)));
  }
  return arr;
}

function drawBars(arr) {
  const margin = 10;
  const barWidth = (W - 2 * margin) / arr.length;
  ctx.clearRect(0, 0, W, H);
  for (let i = 0; i < arr.length; i++) {
    ctx.beginPath();
    ctx.rect(margin + i * barWidth, H - arr[i], barWidth - 2, -H);
    ctx.strokeStyle = 'black';
    ctx.stroke();
    ctx.closePath();
  }
}

const arr = makeArray(100, Math.random() < 0.5 ? 'Random' : 'Reverse');
drawBars(arr);

